1           0.0593            0.174        0.115     0.0119      0.0925
# ℹ 1 more variable: interaction &lt;dbl&gt;



# Channel-level composition, rate, and contribution views for the focal comparison
channel_compare &lt;- npl_panel |&gt;
  filter(origination_quarter %in% c(t1_label, t2_label)) |&gt;
  group_by(origination_quarter) |&gt;
  mutate(share = n / sum(n)) |&gt;
  ungroup()

channel_effects &lt;- channel_compare |&gt;
  select(origination_quarter, channel, share, npl_rate) |&gt;
  pivot_wider(
    names_from = origination_quarter,
    values_from = c(share, npl_rate),
    names_sep = "_"
  ) |&gt;
  mutate(
    mix_effect = (.data[[paste0("share_", t2_label)]] - .data[[paste0("share_", t1_label)]]) *
                 .data[[paste0("npl_rate_", t1_label)]],
    rate_effect = .data[[paste0("share_", t1_label)]] *
                  (.data[[paste0("npl_rate_", t2_label)]] - .data[[paste0("npl_rate_", t1_label)]]),
    interaction = (.data[[paste0("share_", t2_label)]] - .data[[paste0("share_", t1_label)]]) *
                  (.data[[paste0("npl_rate_", t2_label)]] - .data[[paste0("npl_rate_", t1_label)]])
  )

channel_compare |&gt;
  select(origination_quarter, channel, share, npl_rate) |&gt;
  pivot_longer(c(share, npl_rate), names_to = "metric", values_to = "value") |&gt;
  mutate(
    metric = recode(metric,
                    share = "Portfolio Composition (channel share)",
                    npl_rate = "Channel NPL Ratio"),
    origination_quarter = factor(origination_quarter, levels = c(t1_label, t2_label))
  ) |&gt;
  ggplot(aes(x = channel, y = value, fill = origination_quarter)) +
  geom_col(position = "dodge") +
  facet_wrap(~ metric, scales = "free_y") +
  scale_y_continuous(labels = scales::percent_format(accuracy = 0.1)) +
  scale_fill_manual(values = c("2022-Q1" = "#2c7bb6", "2023-Q3" = "#d7191c")) +
  labs(
    title = paste("What changed between", t1_label, "and", t2_label, "?"),
    x = NULL, y = NULL, fill = NULL
  ) +
  theme_minimal()







channel_effects |&gt;
  select(channel, mix_effect, rate_effect, interaction) |&gt;
  pivot_longer(-channel, names_to = "component", values_to = "value") |&gt;
  mutate(component = factor(component, levels = c("mix_effect", "rate_effect", "interaction"))) |&gt;
  ggplot(aes(x = channel, y = value, fill = component)) +
  geom_col() +
  scale_y_continuous(labels = scales::percent_format(accuracy = 0.1)) +
  scale_fill_manual(
    values = c(mix_effect = "#e41a1c", rate_effect = "#377eb8", interaction = "#984ea3"),
    labels = c(mix_effect = "Mix", rate_effect = "Rate", interaction = "Interaction")
  ) +
  labs(
    title = paste("Where the NPL change comes from:", t1_label, "→", t2_label),
    x = NULL, y = "Contribution to portfolio ΔNPL", fill = "Component"
  ) +
  theme_minimal()









# Visualise mix vs rate effects across all adjacent quarter pairs
quarter_pairs &lt;- tibble(
  t1 = c("2022-Q1","2022-Q2","2022-Q3","2022-Q4","2023-Q1","2023-Q2","2023-Q3"),
  t2 = c("2022-Q2","2022-Q3","2022-Q4","2023-Q1","2023-Q2","2023-Q3","2023-Q4")
)

decomp_ts &lt;- purrr::map2_dfr(quarter_pairs$t1, quarter_pairs$t2, function(t1, t2) {
  make_decomp(npl_panel, t1, t2) |&gt; mutate(period = paste(t1, "→", t2))
})

decomp_ts |&gt;
  select(period, mix_effect, rate_effect, interaction) |&gt;
  pivot_longer(-period, names_to = "component", values_to = "value") |&gt;
  mutate(period = factor(period, levels = unique(period))) |&gt;
  ggplot(aes(x = period, y = value, fill = component)) +
  geom_col() +
  scale_y_continuous(labels = scales::percent_format(accuracy = 0.1)) +
  scale_fill_manual(values = c(mix_effect  = "#e41a1c",
                               rate_effect = "#377eb8",
                               interaction = "#984ea3")) +
  labs(title = "Shift-Share Decomposition of NPL Change by Quarter Pair",
       x = NULL, y = "Contribution to ΔNPL", fill = "Component") +
  theme_minimal() +
  theme(axis.text.x = element_text(angle = 35, hjust = 1))








In the 2022-Q1 → 2023-Q3 decomposition, the mix effect accounts for 10% of total NPL deterioration and the rate-within-channel effect for 81%.
Interpretation for action: if mix is dominant, tighten channel controls or pause digital partner volumes; if rate-within-channel is dominant, investigate how each channel’s risk profile changed independently of composition.
The next section deep-dives into within-segment performance changes using behavioral indicators, SHAP attribution, uplift estimates, and macro residual diagnostics to distinguish policy, behavior, and operational effects.

Approach W: Three Models, Blended
This is the cleaner one to write — glm does all the work. We fit one model per segment, then blend their predicted probabilities. The single weight w_target controls how much we lean on the target segment’s model.

fit_glm &lt;- function(tr) {
  glm(y ~ ., data = cbind(tr$df, y = tr$y), family = binomial())
}

score_W &lt;- function(models, newdf, w_target = 0.55) {
  w_ref &lt;- (1 - w_target) / 2
  w_target * predict(models$target, newdf, type = "response") +
  w_ref    * predict(models$ref1,   newdf, type = "response") +
  w_ref    * predict(models$ref2,   newdf, type = "response")
}

w_target = 1 is “target only”; w_target = 1/3 treats all three segments equally.

Required Packages

library(dplyr)
library(tidyr)
library(ggplot2)
library(knitr)
theme_set(theme_minimal(base_size = 12))

A couple of dependency-free helpers — a rank-based AUC and a Brier score (mean squared error of the predicted probability, which rewards good calibration as well as good ranking):

auc &lt;- function(y, s) {
  r &lt;- rank(s); n1 &lt;- sum(y); n0 &lt;- length(y) - n1
  (sum(r[y == 1]) - n1 * (n1 + 1) / 2) / (n1 * n0)
}
brier &lt;- function(y, p) mean((p - y)^2)

calib_tbl &lt;- function(y, p, bins = 10) {
  b &lt;- cut(p, breaks = seq(0, 1, length.out = bins + 1), include.lowest = TRUE)
  data.frame(y = y, p = p, b = b) |&gt;
    group_by(b) |&gt;
    summarise(mean_p = mean(p), mean_y = mean(y), n = dplyr::n(), .groups = "drop")
}

Metrics and helpers
We score with AUC (rank-based) and KS, and use a small wrapper around glm so we can pass weights and offsets cleanly.

auc &lt;- function(s, y) {
  if (length(unique(y)) &lt; 2) return(NA_real_)
  r &lt;- rank(s, ties.method = "average"); n1 &lt;- sum(y == 1); n0 &lt;- sum(y == 0)
  (sum(r[y == 1]) - n1 * (n1 + 1) / 2) / (n1 * n0)
}
ks &lt;- function(s, y) {
  if (length(unique(y)) &lt; 2) return(NA_real_)
  o &lt;- order(s); max(abs(cumsum(y[o] == 1)/sum(y == 1) - cumsum(y[o] == 0)/sum(y == 0)))
}
pr  &lt;- function(m, nd) as.vector(predict(m, nd, type = "response"))
fml &lt;- as.formula(paste("y ~", paste(feat_names, collapse = " + ")))

qglm &lt;- function(formula, data, weights) {
  cl &lt;- list(quote(stats::glm), formula = formula, family = quote(binomial()))
  if (!missing(data))    cl$data    &lt;- data
  if (!missing(weights)) cl$weights &lt;- weights
  suppressWarnings(eval(as.call(cl), parent.frame()))
}
strat_idx &lt;- function(seg, frac, seed) {
  set.seed(seed)
  unlist(lapply(segments, function(s){ i &lt;- which(seg == s); sample(i, floor(frac * length(i))) }))
}
